<?php
namespace App\Http\Controllers\API;
use App\Http\Controllers\Controller;use App\Http\Resources\{JobOpeningResource,CandidateResource,GoalResource};use App\Models\{JobOpening,Candidate,PerformanceGoal,PerformanceReview};use Illuminate\Http\Request;use Illuminate\Http\JsonResponse;
class PhaseFourController extends Controller{public function openings(Request $r){return JobOpeningResource::collection(JobOpening::where('owner_id',$r->user()->workspaceOwnerId())->latest()->get());}public function storeOpening(Request $r):JsonResponse{$d=$r->validate(['title'=>'required|string|max:255','department'=>'nullable|string|max:100']);$x=JobOpening::create([...$d,'owner_id'=>$r->user()->workspaceOwnerId(),'opened_at'=>now()->toDateString()]);return response()->json(new JobOpeningResource($x),201);}public function candidates(Request $r){return CandidateResource::collection(Candidate::where('owner_id',$r->user()->workspaceOwnerId())->latest()->get());}public function storeCandidate(Request $r):JsonResponse{$d=$r->validate(['job_opening_id'=>'nullable|exists:job_openings,id','name'=>'required|string|max:255','email'=>'required|email','stage'=>'nullable|string|max:50','notes'=>'nullable|string']);$x=Candidate::create([...$d,'owner_id'=>$r->user()->workspaceOwnerId()]);return response()->json(new CandidateResource($x),201);}public function goals(Request $r){return GoalResource::collection(PerformanceGoal::where('owner_id',$r->user()->workspaceOwnerId())->latest()->get());}public function storeGoal(Request $r):JsonResponse{$d=$r->validate(['staff_id'=>'required|exists:staff,id','title'=>'required|string|max:255','description'=>'nullable|string','progress'=>'nullable|integer|min:0|max:100','due_date'=>'nullable|date']);$r->user()->workspaceStaff()->findOrFail($d['staff_id']);$x=PerformanceGoal::create([...$d,'owner_id'=>$r->user()->workspaceOwnerId()]);return response()->json(new GoalResource($x),201);}public function reviews(Request $r){return response()->json(PerformanceReview::where('owner_id',$r->user()->workspaceOwnerId())->latest()->get());}}
